    "p.a2-06.1": "Was ziehst du zur Party an?",
    "p.a2-06.2": "Kann ich das anprobieren?",
    "p.a2-06.3": "Es passt dir sehr gut.",
    "p.a2-06.4": "Es ist zu groß für mich.",
    "p.a2-06.5": "Wie sieht er aus?",
    "p.a2-06.6": "Sie hat lange dunkle Haare.",
    "p.a2-06.7": "Er ist größer als ich.",
    "p.a2-06.8": "Dieses hier ist besser als das da.",
    "p.a2-06.9": "Sie ist die eleganteste Frau im Büro.",
    "p.a2-06.10": "Er trägt eine Brille.",
    "p.a2-06.11": "Nimm einen Mantel, draußen ist es kalt.",
    "p.a2-06.12": "Du siehst toll aus!",
    "s.a2-06.1": "Heute trage ich Jeans, ein weißes T-Shirt und eine Jacke.",
    "s.a2-06.2": "Meine Schwester ist kleiner als ich, aber sie ist stärker.",
    "s.a2-06.3": "Dieses Kleid ist eleganter als der Rock.",
    "s.a2-06.4": "Er ist ein großer, dünner Mann mit blonden Haaren und Brille.",
    "s.a2-06.5": "Diese Schuhe sind besser als jene, aber teurer.",
    "s.a2-06.6": "Im Winter tragen wir einen Mantel, einen Hut und einen Schal.",
    "s.a2-06.7": "Meine Großmutter ist die freundlichste Person in der Familie.",
    "s.a2-06.8": "Ich habe die Hose anprobiert, aber sie hat nicht gepasst.",
    "s.a2-06.9": "Das Wetter ist heute schlechter als gestern.",
    "s.a2-06.10": "Schwarze Socken sind billiger als die roten.",
    "s.a2-06.11": "Sie mag Mode und trägt immer schöne Kleidung.",
    "s.a2-06.12": "Mein Bruder ist der bestaussehende Student in seiner Klasse.",
    "d.a2-06.1": "Michal, wer ist die Frau neben deinem Chef?",
    "d.a2-06.2": "Welche? Die große mit den langen dunklen Haaren?",
    "d.a2-06.3": "Nein, die kleinere mit Brille und rotem Kleid.",
    "d.a2-06.4": "Ah, das ist Dana, unsere neue Kollegin. Sie ist sehr freundlich.",
    "d.a2-06.5": "Sie ist sehr elegant. Mir gefällt ihre Jacke.",
    "d.a2-06.6": "Ja, sie liebt Mode. Sie trägt immer bessere Kleidung als ich!",
    "d.a2-06.7": "Und wer ist der Mann mit den blonden Haaren und dem blauen Hemd?",
    "d.a2-06.8": "Das ist ihr Mann. Er ist älter als sie, glaube ich.",
    "d.a2-06.9": "Er sieht nett aus.",
    "d.a2-06.10": "Das ist er. Komm, ich stelle dich vor.",
    "m.a2-06": "Mein Freund ... ist groß / klein und hat ... Haare. Normalerweise trägt er ... . Er ist größer als ich, aber ich bin ... als er. Er ist der ... Mensch, den ich kenne.",
