    "p.a2-07.1": "Rate mal, was mir passiert ist!",
    "p.a2-07.2": "Es war einmal...",
    "p.a2-07.3": "Was ist dann passiert?",
    "p.a2-07.4": "Plötzlich ging das Licht aus.",
    "p.a2-07.5": "Ich wurde 1990 geboren.",
    "p.a2-07.6": "Ich bin in einem kleinen Dorf aufgewachsen.",
    "p.a2-07.7": "Glücklicherweise wurde niemand verletzt.",
    "p.a2-07.8": "Das ist nicht dein Ernst!",
    "p.a2-07.9": "Ich konnte es nicht glauben.",
    "p.a2-07.10": "Am Ende war alles in Ordnung.",
    "p.a2-07.11": "Während ich schlief, klingelte das Telefon.",
    "p.a2-07.12": "Erzähl mir die ganze Geschichte.",
    "s.a2-07.1": "Als ich ein Kind war, wohnten wir in der Nähe des Meeres.",
    "s.a2-07.2": "Zuerst habe ich meine Schlüssel verloren, dann habe ich sie in meiner Tasche gefunden.",
    "s.a2-07.3": "Während wir aßen, erzählte mein Bruder eine lange Geschichte.",
    "s.a2-07.4": "Plötzlich fiel sie hin und brach sich den Arm.",
    "s.a2-07.5": "Meine Eltern haben vor dreißig Jahren geheiratet.",
    "s.a2-07.6": "Er sagte, dass er am Flughafen eine berühmte Person gesehen hat.",
    "s.a2-07.7": "Wir haben gewonnen und alle haben gelacht und gesungen.",
    "s.a2-07.8": "Es gab einen Unfall auf der Straße, aber glücklicherweise wurde niemand verletzt.",
    "s.a2-07.9": "Es war ein wunderbares Abenteuer vom Anfang bis zum Ende.",
    "s.a2-07.10": "Leider war die Party schon vorbei, als wir ankamen.",
    "s.a2-07.11": "Das Baby hat die ganze Nacht geweint und wir sind immer noch müde.",
    "s.a2-07.12": "In diesem Moment verstand ich, dass es eine Überraschungsparty war.",
    "d.a2-07.1": "Oma, erzähl mir eine Geschichte aus deiner Kindheit.",
    "d.a2-07.2": "Einmal, als ich acht war, bin ich mit meinem Bruder an den Strand gegangen.",
    "d.a2-07.3": "Nur ihr zwei? Ohne eure Eltern?",
    "d.a2-07.4": "Ja! Während wir schwammen, fing es plötzlich an zu regnen.",
    "d.a2-07.5": "Was ist dann passiert?",
    "d.a2-07.6": "Wir sind nach Hause gerannt, aber ich bin hingefallen und habe einen Schuh verloren.",
    "d.a2-07.7": "Oh nein! Hast du ihn gefunden?",
    "d.a2-07.8": "Nein, leider nicht. Meine Mutter war wütend, aber dann hat sie gelacht.",
    "d.a2-07.9": "Und dein Bruder?",
    "d.a2-07.10": "Er erzählt diese Geschichte immer noch bei jedem Familienessen!",
    "d.a2-07.11": "Ich liebe deine Geschichten, Oma.",
    "m.a2-07": "Letzten ... war ich ... , als plötzlich ... . Zuerst habe ich ... , dann habe ich ... . Glücklicherweise ... . Am Ende ... .",
