    "p.a2-08.1": "Was machst du nächstes Wochenende?",
    "p.a2-08.2": "Ich werde meine Eltern besuchen.",
    "p.a2-08.3": "Möchtest du zu meinem Geburtstag kommen?",
    "p.a2-08.4": "Sehr gern!",
    "p.a2-08.5": "Tut mir leid, ich kann nicht. Ich habe andere Pläne.",
    "p.a2-08.6": "Vielleicht nächstes Mal.",
    "p.a2-08.7": "Bis bald!",
    "p.a2-08.8": "Ich hoffe es.",
    "p.a2-08.9": "Was wirst du nach dem Kurs machen?",
    "p.a2-08.10": "Ich rufe dich später an.",
    "p.a2-08.11": "Bist du bereit?",
    "p.a2-08.12": "Versprochen!",
    "s.a2-08.1": "Nächstes Jahr werde ich im Ausland studieren.",
    "s.a2-08.2": "Wenn es morgen regnet, bleiben wir zu Hause.",
    "s.a2-08.3": "Meine Schwester heiratet im Juni; wir organisieren die Hochzeit.",
    "s.a2-08.4": "Sie werden bald in eine größere Wohnung umziehen.",
    "s.a2-08.5": "Ich spare Geld, weil ich nach Japan reisen will.",
    "s.a2-08.6": "Wir werden seinen Geburtstag wahrscheinlich im Restaurant feiern.",
    "s.a2-08.7": "Sie hat mit zehn Jahren entschieden, Ärztin zu werden.",
    "s.a2-08.8": "Kommst du am Freitag mit uns zum Konzert?",
    "s.a2-08.9": "Mein Traum ist es, eines Tages meine eigene Firma zu haben.",
    "s.a2-08.10": "Ich verspreche, dass ich versuchen werde, früh zu kommen.",
    "s.a2-08.11": "Was ist das Datum der Hochzeit? Der zwanzigste Mai.",
    "s.a2-08.12": "Es ist unmöglich, das Projekt diese Woche zu beenden.",
    "d.a2-08.1": "Nir, was machst du nächsten Samstag?",
    "d.a2-08.2": "Ich weiß noch nicht. Warum?",
    "d.a2-08.3": "Ich habe Geburtstag und werde zu Hause eine Party machen. Möchtest du kommen?",
    "d.a2-08.4": "Sehr gern! Um wie viel Uhr?",
    "d.a2-08.5": "Um acht. Ich werde kochen, und Maya bringt die Musik mit.",
    "d.a2-08.6": "Super. Kann ich etwas mitbringen?",
    "d.a2-08.7": "Vielleicht einen Kuchen? Wenn du Zeit hast.",
    "d.a2-08.8": "Bestimmt. Ich mache einen Schokoladenkuchen. Wie viele Leute kommen?",
    "d.a2-08.9": "Wahrscheinlich fünfzehn. Und nächsten Monat feiern wir wieder: die Hochzeit meiner Schwester!",
    "d.a2-08.10": "Wow, herzlichen Glückwunsch! Dann bis Samstag.",
    "m.a2-08": "Nächsten ... werde ich ... . Wahrscheinlich werde ich ... . Wenn ich Zeit habe, werde ich ... . Mein Traum ist es, ... . Ich hoffe, bald ... .",
