    "p.a2-09.1": "Wie fühlst du dich?",
    "p.a2-09.2": "Ich bin heute gut gelaunt.",
    "p.a2-09.3": "Meiner Meinung nach ist das eine gute Idee.",
    "p.a2-09.4": "Ich stimme dir zu.",
    "p.a2-09.5": "Ich bin nicht einverstanden.",
    "p.a2-09.6": "Ich denke, dass du recht hast.",
    "p.a2-09.7": "Mach dir keine Sorgen!",
    "p.a2-09.8": "Was ist los?",
    "p.a2-09.9": "Beruhige dich.",
    "p.a2-09.10": "Das kommt mir seltsam vor.",
    "p.a2-09.11": "Wirklich? Das kann ich nicht glauben!",
    "p.a2-09.12": "Das ist nicht wahr.",
    "s.a2-09.1": "Ich bin sehr glücklich, weil meine Schwester zu Besuch kommt.",
    "s.a2-09.2": "Er ärgert sich, wenn der Zug Verspätung hat.",
    "s.a2-09.3": "Meine Mutter sorgt sich, wenn ich nachts spät zurückkomme.",
    "s.a2-09.4": "Wir hatten am Samstag auf der Party viel Spaß.",
    "s.a2-09.5": "Sie war vor dem Vorstellungsgespräch nervös, aber jetzt ist sie ruhig.",
    "s.a2-09.6": "Meiner Meinung nach war der Film seltsam und zu lang.",
    "s.a2-09.7": "Die Kinder langweilen sich, wenn es den ganzen Tag regnet.",
    "s.a2-09.8": "Sie haben sich während einer Reise nach Italien verliebt.",
    "s.a2-09.9": "Ich denke, dass Gesundheit wichtiger ist als Geld.",
    "s.a2-09.10": "Er beschwert sich immer über das Wetter, aber heute stimme ich ihm zu.",
    "s.a2-09.11": "Ich war überrascht und stolz, als mein Sohn die Prüfung bestanden hat.",
    "s.a2-09.12": "Sie fühlt sich in der neuen Stadt einsam und traurig.",
    "d.a2-09.1": "Keren, du scheinst traurig. Was ist los?",
    "d.a2-09.2": "Ich bin besorgt. Meine Firma will, dass ich in eine andere Stadt ziehe.",
    "d.a2-09.3": "Wirklich? Und was denkst du?",
    "d.a2-09.4": "Ich weiß nicht. Die Stelle ist besser, aber ich werde mich dort einsam fühlen.",
    "d.a2-09.5": "Meiner Meinung nach ist das eine tolle Chance.",
    "d.a2-09.6": "Vielleicht, aber ich habe Angst vor Veränderungen.",
    "d.a2-09.7": "Am Anfang ist jeder nervös. Dann hat man Spaß und lernt neue Leute kennen.",
    "d.a2-09.8": "Das ist wahr. Mein Freund stimmt dir natürlich zu.",
    "d.a2-09.9": "Mach dir nicht so viele Sorgen. Denk in Ruhe darüber nach.",
    "d.a2-09.10": "Du hast recht. Danke, Amir. Ich fühle mich schon ruhiger.",
    "m.a2-09": "Heute fühle ich mich ... , weil ... . Ich ärgere mich, wenn ... . Meiner Meinung nach ist ... ... . Ich denke, dass ... . Ich stimme ... zu / nicht zu.",
