    "p.a2-10.1": "Hallo, wer spricht da?",
    "p.a2-10.2": "Kann ich bitte mit Dana sprechen?",
    "p.a2-10.3": "Einen Moment bitte, bleiben Sie dran.",
    "p.a2-10.4": "Sie ist nicht da. Möchten Sie eine Nachricht hinterlassen?",
    "p.a2-10.5": "Ich rufe dich später zurück.",
    "p.a2-10.6": "Schick mir das Foto per Nachricht.",
    "p.a2-10.7": "Wie ist das WLAN-Passwort?",
    "p.a2-10.8": "Mein Akku ist leer.",
    "p.a2-10.9": "Das Internet funktioniert nicht.",
    "p.a2-10.10": "Schalten Sie bitte Ihr Telefon aus.",
    "p.a2-10.11": "Ich schicke es dir per E-Mail.",
    "p.a2-10.12": "Hast du meine Nachricht bekommen?",
    "s.a2-10.1": "Ich rufe meine Großmutter jeden Sonntag an, aber sie geht nie ans Telefon.",
    "s.a2-10.2": "Mein Laptop ist kaputt, also arbeite ich auf meinem Handy.",
    "s.a2-10.3": "Sie hat mir ein Video geschickt und ich habe es mit meinen Freunden geteilt.",
    "s.a2-10.4": "Obwohl das Hotel WLAN hat, ist das Internet sehr langsam.",
    "s.a2-10.5": "Ich habe die App heruntergeladen, aber ich habe mein Passwort vergessen.",
    "s.a2-10.6": "Er postet jeden Tag Fotos in den sozialen Medien.",
    "s.a2-10.7": "Bitte lade die Kamera vor der Reise auf.",
    "s.a2-10.8": "Ich habe deine E-Mail bekommen; ich kann die Datei jedoch nicht öffnen.",
    "s.a2-10.9": "Schalte den Computer ein und such die Webseite.",
    "s.a2-10.10": "Meine Eltern sind jetzt online, also kann ich sie anrufen.",
    "s.a2-10.11": "Der Bildschirm ist schwarz, weil der Akku leer ist.",
    "s.a2-10.12": "Ich habe ihr gestern geschrieben, aber sie hat noch nicht geantwortet.",
    "d.a2-10.1": "Hallo, Ori? Hier ist Tal.",
    "d.a2-10.2": "Hi Tal! Ich kann dich nicht gut hören. Wo bist du?",
    "d.a2-10.3": "Im Zug. Das Internet hier ist furchtbar.",
    "d.a2-10.4": "Okay. Hast du die E-Mail mit den Fotos von der Reise bekommen?",
    "d.a2-10.5": "Ja, ich habe sie heruntergeladen, aber ich kann das Video nicht öffnen.",
    "d.a2-10.6": "Seltsam. Ich schicke es dir noch einmal per Nachricht.",
    "d.a2-10.7": "Danke. Und poste das Foto von mir am Strand nicht in den sozialen Medien!",
    "d.a2-10.8": "Obwohl es ein tolles Foto ist? Okay, okay.",
    "d.a2-10.9": "Hör mal, mein Akku ist fast leer. Ich rufe dich heute Abend zurück.",
    "d.a2-10.10": "Gut. Lad dein Handy auf! Tschüss.",
    "m.a2-10": "Ich benutze mein Handy, um ... und ... . Gestern war mein ... kaputt, also habe ich ... . Obwohl ... , habe ich ... . Ich habe ... an ... geschickt und sie haben ... geantwortet.",
