    "p.b1-01.1": "Hast du die neueste Folge gesehen?",
    "p.b1-01.2": "Ich kann es sehr empfehlen.",
    "p.b1-01.3": "Die Kritiken waren gemischt.",
    "p.b1-01.4": "Es basiert auf einer wahren Geschichte.",
    "p.b1-01.5": "Was läuft heute Abend?",
    "p.b1-01.6": "Ich konnte nicht aufhören zu schauen.",
    "p.b1-01.7": "Das Ende war enttäuschend.",
    "p.b1-01.8": "Lass uns es mit Untertiteln anschauen.",
    "p.b1-01.9": "Die Karten waren in einer Stunde ausverkauft.",
    "p.b1-01.10": "Das ist nicht wirklich mein Genre.",
    "p.b1-01.11": "Das Publikum gab ihnen stehende Ovationen.",
    "s.b1-01.1": "Ich habe noch nie einen so faszinierenden Dokumentarfilm gesehen.",
    "s.b1-01.2": "Die Serie wurde letztes Jahr auf einem neuen Sender ausgestrahlt.",
    "s.b1-01.3": "Die Kritiker schrieben ausgezeichnete Rezensionen über die Aufführung.",
    "s.b1-01.4": "Hast du ihren Kanal schon abonniert?",
    "s.b1-01.5": "Der Handlung des Films war schwer zu folgen.",
    "s.b1-01.6": "Die Ausstellung wurde letzte Woche eröffnet und hat riesige Besuchermengen angezogen.",
    "s.b1-01.7": "Die Hauptfigur verändert sich im Laufe der Serie sehr.",
    "s.b1-01.8": "Der Journalist interviewte den Prominenten nach der Premiere.",
    "s.b1-01.9": "Das Publikum applaudierte am Ende zehn Minuten lang.",
    "s.b1-01.10": "Viele junge Leute sehen Filme lieber mit Untertiteln.",
    "s.b1-01.11": "Die Ausstellung feiert das kulturelle Erbe der Region.",
    "d.b1-01.1": "Hast du die neue Serie gesehen, über die alle reden?",
    "d.b1-01.2": "Noch nicht. Ich habe nur eine Rezension in der Zeitung gelesen.",
    "d.b1-01.3": "Die Kritiker waren begeistert, besonders von der Hauptfigur.",
    "d.b1-01.4": "Ist die Handlung kompliziert? Ich bin zu müde für etwas Schweres.",
    "d.b1-01.5": "Überhaupt nicht, sie ist unterhaltsam und die Folgen sind kurz.",
    "d.b1-01.6": "Welcher Sender strahlt sie aus?",
    "d.b1-01.7": "Keiner. Man muss einen Streamingdienst abonnieren.",
    "d.b1-01.8": "Gut. Gibt es hebräische Untertitel?",
    "d.b1-01.9": "Ja, und der Soundtrack ist ein Meisterwerk.",
    "d.b1-01.10": "Du hast mich überzeugt. Lass uns heute Abend die erste Folge anschauen.",
    "m.b1-01": "Ich habe gerade ... zu Ende geschaut. In der Handlung geht es um ... . Die Hauptfigur ist ... . Mir hat ... gefallen, aber ... . Ich würde es ... empfehlen.",
