    "w.b1-02.trail": "der Wanderweg",
    "w.b1-02.shade": "der Schatten",
    "p.b1-02.1": "Es ist nur eine Frage der Zeit, bis die Art verschwindet.",
    "p.b1-02.2": "Wir sollten weniger Plastik verwenden.",
    "p.b1-02.3": "Der Fluss war früher viel sauberer.",
    "p.b1-02.4": "Lass uns den Weg am See entlang nehmen.",
    "p.b1-02.5": "Es hat seit Monaten nicht geregnet.",
    "p.b1-02.6": "Jede Kleinigkeit hilft.",
    "p.b1-02.7": "Die Aussicht vom Gipfel war atemberaubend.",
    "p.b1-02.8": "Lass keinen Abfall zurück.",
    "p.b1-02.9": "Der Wald ist die Heimat von Hunderten von Arten.",
    "p.b1-02.10": "Auf dem Rückweg geriet wir in einen Sturm.",
    "p.b1-02.11": "Der Umstieg auf Solarenergie ist hier sinnvoll.",
    "s.b1-02.1": "Während wir wanderten, sahen wir eine Familie von Rehen.",
    "s.b1-02.2": "Die Gletscher schmolzen schneller, als die Wissenschaftler erwartet hatten.",
    "s.b1-02.3": "Mein Großvater pflanzte früher jeden Frühling einen Baum.",
    "s.b1-02.4": "Die Dürre zerstörte letzten Sommer den Großteil der Ernte.",
    "s.b1-02.5": "Die Verschmutzung durch die Fabrik bedrohte die Tierwelt im Fluss.",
    "s.b1-02.6": "Wir recyceln zu Hause Glas, Papier und Plastik.",
    "s.b1-02.7": "Das Dorf überlebte die Überschwemmung dank der neuen Mauer.",
    "s.b1-02.8": "Erneuerbare Energie könnte die Emissionen deutlich reduzieren.",
    "s.b1-02.9": "Die Sonne schien, als wir das Ende des Wanderwegs erreichten.",
    "s.b1-02.10": "Viele gefährdete Arten leben nur in diesem Wald.",
    "s.b1-02.11": "Der Boden hier ist zu trocken, um Gemüse anzubauen.",
    "d.b1-02.1": "Wie war deine Reise in die Berge?",
    "d.b1-02.2": "Wunderbar. Wir sind einen Wanderweg gegangen, der durch einen alten Wald führt.",
    "d.b1-02.3": "Habt ihr wilde Tiere gesehen?",
    "d.b1-02.4": "Wir waren gerade beim Mittagessen, als ein Fuchs direkt an uns vorbeilief.",
    "d.b1-02.5": "Unglaublich! War die Landschaft so grün wie auf den Fotos?",
    "d.b1-02.6": "Nicht wirklich. Der Fluss war wegen der Dürre fast leer.",
    "d.b1-02.7": "Das ist traurig. Das Klima verändert sich wirklich.",
    "d.b1-02.8": "Ja. Unser Führer sagte, der Gletscher habe früher bis ins Tal gereicht.",
    "d.b1-02.9": "Haben die Leute Abfall am Weg zurückgelassen?",
    "d.b1-02.10": "Leider ja. Wir haben auf dem Weg nach unten zwei Säcke Plastik gesammelt.",
    "m.b1-02": "Letzten Sommer sind wir nach ... gefahren. Das Wetter war ... und die Landschaft war ... . Während wir ..., plötzlich ... . Am Ende ... .",
