    "w.b1-03.gathering": "das Treffen",
    "p.b1-03.1": "Wir verstehen uns richtig gut.",
    "p.b1-03.2": "Ich schulde dir eine Entschuldigung.",
    "p.b1-03.3": "Lass uns in Kontakt bleiben.",
    "p.b1-03.4": "Es war nur ein Missverständnis.",
    "p.b1-03.5": "Du kannst immer auf mich zählen.",
    "p.b1-03.6": "Ich möchte mich lieber nicht einmischen.",
    "p.b1-03.7": "Sie haben sich letzten Monat getrennt.",
    "p.b1-03.8": "Möchtest du am Freitag mitkommen?",
    "p.b1-03.9": "Ich mache es wieder gut, versprochen.",
    "p.b1-03.10": "Nimm es nicht persönlich.",
    "p.b1-03.11": "Ich schätze deine Unterstützung sehr.",
    "s.b1-03.1": "Nächstes Jahr werde ich mich im Gemeindezentrum ehrenamtlich engagieren.",
    "s.b1-03.2": "Ein treuer Freund unterstützt dich auch in schweren Zeiten.",
    "s.b1-03.3": "Wenn ich du wäre, würde ich mich heute Abend bei ihr entschuldigen.",
    "s.b1-03.4": "Sie stritten sich über Geld, aber am Ende schlossen sie einen Kompromiss.",
    "s.b1-03.5": "Das Paar ist seit fast zehn Jahren zusammen.",
    "s.b1-03.6": "Eifersucht kann sogar eine starke Beziehung zerstören.",
    "s.b1-03.7": "Ich würde niemals über einen engen Freund tratschen.",
    "s.b1-03.8": "Sie ist kontaktfreudig und macht überall neue Bekanntschaften.",
    "s.b1-03.9": "Wir sehen uns am Samstagabend beim Treffen.",
    "s.b1-03.10": "Unsere Gemeinschaft ermutigt junge Menschen, sich zugehörig zu fühlen.",
    "s.b1-03.11": "Eine großzügige Einstellung hilft Menschen, leichter zu vergeben.",
    "d.b1-03.1": "Du siehst bedrückt aus. Ist etwas mit Dana passiert?",
    "d.b1-03.2": "Wir hatten gestern einen großen Streit. Ich glaube, sie ist immer noch wütend.",
    "d.b1-03.3": "Worum ging es?",
    "d.b1-03.4": "Sie glaubt, ich hätte über sie getratscht, aber es war ein Missverständnis.",
    "d.b1-03.5": "Hast du versucht, mit ihr zu reden?",
    "d.b1-03.6": "Noch nicht. Ich habe Angst, dass sie mir nicht mehr vertraut.",
    "d.b1-03.7": "Wenn ich du wäre, würde ich sie heute Abend anrufen und mich entschuldigen.",
    "d.b1-03.8": "Du hast recht. Ich lade sie dieses Wochenende auf einen Kaffee ein.",
    "d.b1-03.9": "Gut. Echte Freunde vergeben einander.",
    "d.b1-03.10": "Danke für die Unterstützung. Ich schätze das wirklich.",
    "m.b1-03": "Mein engster Freund ist ... . Wir haben uns ... kennengelernt. Wir verstehen uns, weil ... . Nächsten Monat werden wir ... . Wenn ich mehr Zeit hätte, würde ich ... .",
