    "p.b1-04.1": "Ich möchte ein Konto eröffnen.",
    "p.b1-04.2": "Könnten Sie bitte dieses Formular ausfüllen?",
    "p.b1-04.3": "Gibt es eine Gebühr für die Überweisung?",
