    "p.b1-04.5": "Ich möchte eine Beschwerde einreichen.",
    "p.b1-04.6": "Bitte unterschreiben Sie unten auf der Seite.",
    "p.b1-04.7": "Welche Dokumente muss ich mitbringen?",
    "p.b1-04.8": "Die Frist ist das Ende des Monats.",
    "p.b1-04.9": "Ich habe Anspruch auf eine vollständige Rückerstattung.",
    "p.b1-04.10": "Sie erhalten eine Bestätigung per E-Mail.",
    "p.b1-04.11": "Kann ich die Gebühr in Raten zahlen?",
    "s.b1-04.1": "Der Sachbearbeiter, der mir geholfen hat, war sehr geduldig.",
    "s.b1-04.2": "Das ist das Formular, das Sie unterschreiben müssen.",
    "s.b1-04.3": "Ich habe Geld in der Filiale abgehoben, die in der Nähe meines Büros liegt.",
    "s.b1-04.4": "Der Kredit, dessen Zinsen ziemlich niedrig sind, muss in fünf Jahren zurückgezahlt werden.",
    "s.b1-04.5": "Die Bank hat eine Gebühr verlangt, die niemand erwähnt hatte.",
    "s.b1-04.6": "Mein Führerschein läuft nächsten Monat ab, also muss ich ihn verlängern.",
    "s.b1-04.7": "Das Amt, wo ich die Genehmigung beantragt habe, schließt um zwölf.",
    "s.b1-04.8": "Die Versicherung hat den Antrag nach zwei Wochen genehmigt.",
    "s.b1-04.9": "Sie brauchen ein Dokument, das Ihre Identität nachweist.",
    "s.b1-04.10": "Sie zahlt einen Teil ihres Gehalts auf ein Sparkonto ein.",
    "s.b1-04.11": "Das Verfahren für eine Rückerstattung wird auf der offiziellen Webseite erklärt.",
    "d.b1-04.1": "Guten Morgen. Wie kann ich Ihnen helfen?",
    "d.b1-04.2": "Ich möchte einen kleinen Kredit beantragen, um meine Küche zu renovieren.",
    "d.b1-04.3": "Natürlich. Haben Sie ein Konto bei unserer Filiale?",
    "d.b1-04.4": "Ja, das Sparkonto, das ich vor zwei Jahren eröffnet habe.",
    "d.b1-04.5": "Sehr gut. Sie brauchen ein Dokument, das Ihr Einkommen nachweist.",
    "d.b1-04.6": "Ich habe meine letzten drei Gehaltsabrechnungen mitgebracht. Wie hoch ist der Zinssatz?",
    "d.b1-04.7": "Vier Prozent, und es gibt eine einmalige Gebühr von zweihundert Schekel.",
    "d.b1-04.8": "Gibt es eine Frist für den Antrag?",
    "d.b1-04.9": "Nein, aber die Genehmigung dauert normalerweise etwa zehn Tage.",
    "d.b1-04.10": "Gut. Wo muss ich unterschreiben?",
    "d.b1-04.11": "Hier, unten auf jeder Seite, bitte.",
    "m.b1-04": "Sehr geehrte Damen und Herren, ich schreibe Ihnen wegen ... . Am ... wurde mir ... in Rechnung gestellt, was ... . Ich möchte ... . Ich freue mich auf Ihre Antwort.",
