    "p.b1-05.11": "Ich packe immer noch Kartons aus.",
    "s.b1-05.1": "Die Küche wurde vom vorherigen Eigentümer renoviert.",
    "s.b1-05.2": "Der Mietvertrag muss von beiden Mietern unterschrieben werden.",
    "s.b1-05.3": "Im Keller wird eine neue Heizungsanlage installiert.",
    "s.b1-05.4": "Das Leck wurde heute Morgen von einem Klempner repariert.",
    "s.b1-05.5": "Unsere alten Möbel werden in einem Abstellraum auf dem Dachboden aufbewahrt.",
    "s.b1-05.6": "Die Wohnung ist geräumig, aber die Lage ist weit vom Zentrum entfernt.",
    "s.b1-05.7": "Die Kaution wird am Ende des Mietvertrags zurückgezahlt.",
    "s.b1-05.8": "Viele junge Paare können sich in der Stadt keine Hypothek leisten.",
    "s.b1-05.9": "Die Immobilie wurde über einen Immobilienmakler verkauft.",
    "s.b1-05.10": "Wir sind ausgezogen, weil die Zimmer zu eng waren.",
    "s.b1-05.11": "In den Vororten werden bezahlbare Wohnungen gebaut.",
    "s.b1-05.12": "Wir haben einen ganzen Monat gebraucht, um uns einzuleben.",
    "d.b1-05.1": "Das ist das Wohnzimmer. Die ganze Wohnung wurde letzten Monat neu gestrichen.",
    "d.b1-05.2": "Sie ist ziemlich geräumig. Ist sie möbliert?",
    "d.b1-05.3": "Teilweise. Die Küche und die Schränke sind inbegriffen.",
    "d.b1-05.4": "Und die Heizung? Es fühlt sich kalt an hier drin.",
    "d.b1-05.5": "Im Herbst wurde eine neue Anlage installiert. Sie funktioniert sehr gut.",
    "d.b1-05.6": "Und das Viertel? Ich brauche einen kurzen Arbeitsweg.",
    "d.b1-05.7": "Der Bahnhof ist fünf Minuten zu Fuß entfernt.",
    "d.b1-05.8": "Wie hoch ist die Miete, und sind die Nebenkosten enthalten?",
    "d.b1-05.9": "Viertausend im Monat, Nebenkosten nicht enthalten. Die Kaution beträgt zwei Monatsmieten.",
    "d.b1-05.10": "Kann der Mietvertrag für zwei Jahre statt für eines unterschrieben werden?",
    "d.b1-05.11": "Ich frage den Vermieter. Er ist normalerweise flexibel.",
    "m.b1-05": "Eine ... Wohnung wird in ... zur Miete angeboten. Die Wohnung wurde ... renoviert und hat ... . Die Nebenkosten sind ... . Der Mietvertrag läuft ... . Die Kaution muss ... bezahlt werden.",
