    "w.b1-06.moderate": "mäßig",
    "p.b1-06.1": "Ich versuche, wieder in Form zu kommen.",
    "p.b1-06.2": "Du solltest weniger Zucker essen.",
    "p.b1-06.3": "Ich habe mit dem Rauchen aufgehört.",
    "p.b1-06.4": "Vergiss nicht, dich vorher aufzuwärmen.",
    "p.b1-06.5": "Ich habe mir beim Training einen Muskel gezerrt.",
    "p.b1-06.6": "Alles in Maßen.",
    "p.b1-06.7": "Wie oft trainierst du?",
    "p.b1-06.8": "Ich habe seit Wochen nicht gut geschlafen.",
    "p.b1-06.9": "Der Arzt hat mir gesagt, ich solle es ruhig angehen.",
    "p.b1-06.10": "Es ist nie zu spät, anzufangen.",
    "p.b1-06.11": "Ich fühle mich in letzter Zeit viel energiegeladener.",
    "s.b1-06.1": "Der Arzt sagte, dass mein Blutdruck ein wenig hoch sei.",
    "s.b1-06.2": "Mein Trainer sagte mir, dass ich mich nach jedem Training dehnen sollte.",
    "s.b1-06.3": "Sie sagte, sie habe aufgehört, Fertignahrung zu essen.",
    "s.b1-06.4": "Er erzählte uns, dass er jeden Morgen vor der Arbeit jogge.",
    "s.b1-06.5": "Eine ausgewogene Ernährung mit genug Protein hilft dir, dich schneller zu erholen.",
    "s.b1-06.6": "Meine Schwester sagte, dass Meditation ihr bei der Schlaflosigkeit geholfen habe.",
    "s.b1-06.7": "Regelmäßige Vorsorgeuntersuchungen sind die beste Form der Vorbeugung.",
    "s.b1-06.8": "Die Krankenschwester sagte, ich hätte seit letztem Jahr drei Kilo zugenommen.",
    "s.b1-06.9": "Gute Gewohnheiten sind leichter beizubehalten, wenn man klein anfängt.",
    "s.b1-06.10": "Er sagte, die Verletzung würde sechs Wochen brauchen, um zu heilen.",
    "s.b1-06.11": "Psychische Gesundheit ist genauso wichtig wie körperliche Fitness.",
    "s.b1-06.12": "Mäßige Bewegung verbessert die Ausdauer und das Wohlbefinden.",
    "d.b1-06.1": "Wie ist deine Vorsorgeuntersuchung gelaufen?",
    "d.b1-06.2": "Größtenteils gut. Der Arzt sagte, mein Blutdruck sei leicht erhöht.",
    "d.b1-06.3": "Hat er dir gesagt, dass du etwas ändern sollst?",
    "d.b1-06.4": "Er hat mir gesagt, ich solle weniger Salz und Fertignahrung essen.",
    "d.b1-06.5": "Das klingt sinnvoll. Und Bewegung?",
    "d.b1-06.6": "Er sagte, dass schon ein mäßiges Training dreimal pro Woche helfen würde.",
    "d.b1-06.7": "Ich jogge jeden Morgen im Park. Warum kommst du nicht mit?",
    "d.b1-06.8": "Ehrlich gesagt bin ich nicht sehr fit. Ich wäre in zwei Minuten außer Atem.",
    "d.b1-06.9": "Wir fangen langsam an und dehnen uns richtig. Ausdauer kommt mit der Zeit.",
    "d.b1-06.10": "In Ordnung. Ich möchte auch Meditation gegen meine Schlaflosigkeit ausprobieren.",
    "d.b1-06.11": "Gute Idee. Kleine Gewohnheiten machen einen großen Unterschied.",
    "m.b1-06": "Letztes Jahr habe ich beschlossen, ... . Mein Arzt sagte, dass ... . Am Anfang war es ..., aber jetzt ... . Mein Freund hat mir gesagt, dass ... . Heute fühle ich mich ... .",
