    "w.b1-07.reform": "die Reform",
    "p.b1-07.1": "Hast du heute Morgen die Nachrichten gehört?",
    "p.b1-07.2": "Ich bezweifle, dass sich etwas ändern wird.",
    "p.b1-07.3": "Wen wirst du wählen?",
    "p.b1-07.4": "Es ist wichtig, dass jeder mitreden kann.",
    "p.b1-07.5": "Der Minister lehnte eine Stellungnahme ab.",
    "p.b1-07.6": "Ich hoffe, die Reform wird verabschiedet.",
    "p.b1-07.7": "Laut der neuesten Umfrage ist das Rennen knapp.",
    "p.b1-07.8": "Das ist Ansichtssache.",
    "p.b1-07.9": "Die Regierung steht unter Druck, zu handeln.",
    "p.b1-07.10": "Tausende gingen aus Protest auf die Straße.",
    "p.b1-07.11": "Ich habe die Politik satt.",
    "s.b1-07.1": "Ich hoffe, dass die neue Regierung die Arbeitslosigkeit senkt.",
    "s.b1-07.2": "Es ist unerlässlich, dass jeder Bürger bei der Wahl wählt.",
    "s.b1-07.3": "Viele Menschen bezweifeln, dass der Kandidat seine Versprechen halten wird.",
    "s.b1-07.4": "Der Minister trat nach dem Korruptionsskandal zurück.",
    "s.b1-07.5": "Die Opposition forderte, dass das Gesetz sofort geändert werde.",
    "s.b1-07.6": "Journalisten berichteten, dass Tausende gegen die neue Steuer demonstrierten.",
    "s.b1-07.7": "Die Partei gewann eine klare Mehrheit im Parlament.",
    "s.b1-07.8": "Es ist traurig, dass Armut in unserer Gesellschaft immer noch so verbreitet ist.",
    "s.b1-07.9": "Die öffentliche Meinung zur Einwanderung hat sich in den letzten Jahren verändert.",
    "s.b1-07.10": "Die Flüchtlinge hoffen, dass die Krise bald endet.",
    "s.b1-07.11": "Freiheit und Gleichheit sind die Grundlage einer demokratischen Gesellschaft.",
    "d.b1-07.1": "Schaust du dir die Wahlergebnisse an?",
    "d.b1-07.2": "Natürlich. Die Umfragen sagen, es wird sehr knapp.",
    "d.b1-07.3": "Ich hoffe, die Opposition gewinnt dieses Mal.",
    "d.b1-07.4": "Warum? Findest du ihre Steuerpolitik besser?",
    "d.b1-07.5": "Nicht nur das. Ich habe die Skandale und die Korruption satt.",
    "d.b1-07.6": "Ich bezweifle, dass irgendeine Partei völlig sauber ist.",
    "d.b1-07.7": "Vielleicht, aber es ist wichtig, dass die Regierung die Armut bekämpft.",
    "d.b1-07.8": "Einverstanden. Und die Arbeitslosigkeit im Norden steigt.",
    "d.b1-07.9": "Hast du heute Morgen gewählt?",
    "d.b1-07.10": "Ja, gleich als Erstes. Das sollte jeder Bürger tun.",
    "d.b1-07.11": "Schau, die ersten Ergebnisse kommen rein!",
    "m.b1-07": "Ein Problem, das mich beunruhigt, ist ... . Viele Bürger haben das Gefühl, dass ... . Ich hoffe, dass die Regierung ... . Es ist wichtig, dass ... . Sonst ... .",
