    "w.b1-08.to-recruit": "rekrutieren",
    "p.b1-08.1": "Ich bewerbe mich um eine Stelle im Marketing.",
    "p.b1-08.2": "Was umfasst die Stelle?",
    "p.b1-08.3": "Ich freue mich darauf, von Ihnen zu hören.",
    "p.b1-08.4": "Sie wurde zur Teamleiterin befördert.",
    "p.b1-08.5": "Ich bin für die Kundenkonten zuständig.",
    "p.b1-08.6": "Können wir die Besprechung auf Donnerstag verschieben?",
    "p.b1-08.7": "Ich möchte über mein Gehalt sprechen.",
    "p.b1-08.8": "Er kann gut mit Menschen umgehen.",
    "p.b1-08.9": "Ich arbeite zweimal pro Woche von zu Hause.",
    "p.b1-08.10": "Sie beschlossen, sie sofort einzustellen.",
    "p.b1-08.11": "Das hängt vom Budget ab.",
    "p.b1-08.12": "Ich arbeite gern unter Druck.",
    "s.b1-08.1": "Meine Karriere hängt davon ab, jedes Jahr neue Fähigkeiten zu lernen.",
    "s.b1-08.2": "Sie hat sich um das Praktikum beworben und es sofort bekommen.",
    "s.b1-08.3": "Der Arbeitgeber bestand darauf, den Vertrag vor Freitag zu unterschreiben.",
    "s.b1-08.4": "Es gelang ihm, bessere Sozialleistungen und ein höheres Einkommen auszuhandeln.",
    "s.b1-08.5": "Ich bin daran interessiert, in Teilzeit als Freiberufler zu arbeiten.",
    "s.b1-08.6": "Mein Kollege ist dafür verantwortlich, neue Mitarbeiter zu rekrutieren.",
    "s.b1-08.7": "Sie beschlossen, die Schulung auf nächsten Monat zu verschieben.",
    "s.b1-08.8": "Ein zuverlässiger Mitarbeiter vermeidet es, in letzter Minute Überstunden zu machen.",
    "s.b1-08.9": "Nach dreißig Jahren in der Firma ging er endlich in Rente.",
    "s.b1-08.10": "Der Manager gab uns nützliches Feedback zu der Aufgabe.",
    "s.b1-08.11": "Jede Herausforderung bei der Arbeit ist eine Gelegenheit, mehr zu erreichen.",
    "s.b1-08.12": "Zwei Angestellte wurden wegen des Skandals entlassen.",
    "d.b1-08.1": "Danke, dass Sie gekommen sind. Erzählen Sie mir von Ihrer Erfahrung.",
    "d.b1-08.2": "Ich arbeite seit fünf Jahren im Vertrieb und betreue hauptsächlich Kundenkonten.",
    "d.b1-08.3": "Warum möchten Sie Ihren derzeitigen Arbeitgeber verlassen?",
    "d.b1-08.4": "Ich suche eine neue Herausforderung und mehr Verantwortung.",
    "d.b1-08.5": "Welche Fähigkeiten würden Sie in diese Position einbringen?",
    "d.b1-08.6": "Ich kann gut verhandeln, und meine Kollegen sagen, ich sei sehr zuverlässig.",
    "d.b1-08.7": "Die Stelle bringt in stressigen Zeiten einige Überstunden mit sich. Ist das ein Problem?",
    "d.b1-08.8": "Überhaupt nicht, solange sie im Voraus geplant sind.",
    "d.b1-08.9": "Wir bieten Schulungen, gute Sozialleistungen und die Chance auf eine Beförderung innerhalb eines Jahres.",
    "d.b1-08.10": "Das klingt nach einer großartigen Gelegenheit. Wann werden Sie voraussichtlich entscheiden?",
    "d.b1-08.11": "Wir melden uns bis Ende nächster Woche bei Ihnen.",
    "m.b1-08": "Hiermit bewerbe ich mich um die Stelle als ... . Ich habe ... Jahre Erfahrung in ... . Ich bin gut in ... und ich interessiere mich für ... . Ich freue mich auf ... .",
