    "w.b2-01.to-concentrate": "sich konzentrieren",
    "w.b2-01.distraction": "die Ablenkung",
    "p.b2-01.1": "Ich wünschte, ich hätte in der Schule mehr gelernt.",
    "p.b2-01.2": "Wenn ich nur mehr Zeit zum Wiederholen hätte.",
    "p.b2-01.3": "Sie macht einen Master in Biologie.",
    "p.b2-01.4": "Die Abgabefrist für den Aufsatz ist Montag.",
    "p.b2-01.5": "Er hat im zweiten Jahr das Studium abgebrochen.",
    "p.b2-01.6": "Ich kann mich bei diesem Lärm nicht konzentrieren.",
    "p.b2-01.7": "Auswendiglernen ist nicht dasselbe wie Verstehen.",
    "p.b2-01.8": "Sie hat ein Vollstipendium bekommen.",
    "p.b2-01.9": "Wenn du dich nicht bis Freitag einschreibst, verlierst du deinen Platz.",
    "p.b2-01.10": "Es ist nie zu spät, an die Universität zurückzukehren.",
    "p.b2-01.11": "Übung macht den Meister.",
    "s.b2-01.1": "Wenn ich ein Stipendium bekommen hätte, hätte ich im Ausland studiert.",
    "s.b2-01.2": "Ich wünschte, der Lehrplan würde mehr kritisches Denken enthalten.",
    "s.b2-01.3": "Sie machte sich sorgfältig Notizen, damit sie vor der Prüfung den Stoff wiederholen konnte.",
    "s.b2-01.4": "Wenn Studierende nicht früh Disziplin erwerben, tun sie sich an der Universität schwer.",
    "s.b2-01.5": "Er hat sein Studium abgebrochen, weil die Studiengebühren zu hoch waren.",
    "s.b2-01.6": "Wenn die Vorlesungen nur aufgezeichnet würden, könnte ich sie später ansehen.",
    "s.b2-01.7": "Begabte Kinder verlieren oft die Motivation, wenn der Unterricht zu leicht ist.",
    "s.b2-01.8": "Eine Lehre ermöglicht es dir, dich zu spezialisieren und dabei ein Gehalt zu verdienen.",
    "s.b2-01.9": "Ihre Abschlussarbeit basiert auf Forschung, die sie zwei Jahre lang betrieben hat.",
    "s.b2-01.10": "Der Tutor schlug vor, dass wir weniger auswendig lernen und mehr verstehen.",
    "s.b2-01.11": "Neugier ist die beste Motivation, um Wissen zu erwerben.",
    "s.b2-01.12": "In vielen Ländern ist die Schulbildung bis zum Alter von achtzehn Jahren verpflichtend.",
    "d.b2-01.1": "Sie wollten über Ihre Möglichkeiten für nächstes Jahr sprechen?",
    "d.b2-01.2": "Ja. Ich bin mir nicht sicher, ob ich mit einem Master weitermachen oder eine Stelle suchen soll.",
    "d.b2-01.3": "Worauf würden Sie sich spezialisieren, wenn Sie weitermachten?",
    "d.b2-01.4": "Wahrscheinlich Bildungsforschung. Das Schreiben meiner Abschlussarbeit hat mir mehr Spaß gemacht als alles andere.",
    "d.b2-01.5": "Das ist ein gutes Zeichen. Haben Sie sich über Stipendien informiert?",
    "d.b2-01.6": "Ein wenig. Hätte ich früher von den Fristen gewusst, hätte ich mich schon beworben.",
    "d.b2-01.7": "Eines ist noch offen, vorausgesetzt, Sie reichen bis Juni ein Forschungsexposé ein.",
    "d.b2-01.8": "Ich wünschte, ich hätte mehr Zeit. Die Hausarbeiten in diesem Semester sind überwältigend.",
    "d.b2-01.9": "Dann planen wir es so, dass Sie jeden Tag eine Stunde am Exposé arbeiten.",
    "d.b2-01.10": "Das klingt machbar. Und wenn das Stipendium nicht klappt?",
    "d.b2-01.11": "Dann könnte ein beruflicher Kurs oder eine Lehre eine gute Alternative sein.",
    "d.b2-01.12": "Danke. Ich fühle mich jetzt viel weniger verloren.",
    "m.b2-01": "Wenn ich eine Sache an meiner Ausbildung ändern könnte, wäre es ... . Ich wünschte, ich hätte ... . Hätte die Schule ... angeboten, hätte ich ... . Heute glaube ich, dass ... .",
