    "p.b2-02.1": "Die Ergebnisse sprechen für sich.",
    "p.b2-02.2": "In der Theorie funktioniert es, aber in der Praxis ist es kompliziert.",
    "p.b2-02.3": "Es befindet sich noch im Versuchsstadium.",
    "p.b2-02.4": "Die Daten stützen diese Schlussfolgerung nicht.",
    "p.b2-02.5": "Im Zweifelsfall den Test wiederholen.",
    "p.b2-02.6": "Technologie ist ein zweischneidiges Schwert.",
    "p.b2-02.7": "Mein Handy ist praktisch veraltet.",
    "p.b2-02.8": "Sichere deine Dateien, falls das System abstürzt.",
    "p.b2-02.9": "Niemand hätte das vorhersagen können.",
    "p.b2-02.10": "Die Wissenschaftler stehen kurz vor einem Durchbruch.",
    "p.b2-02.11": "Solange es sicher ist, habe ich nichts dagegen, es zu benutzen.",
    "s.b2-02.1": "Wenn man Wasser auf hundert Grad erhitzt, kocht es.",
    "s.b2-02.2": "Wenn das Experiment gelingt, wird das Team die Daten nächstes Jahr veröffentlichen.",
    "s.b2-02.3": "Wenn Wissenschaftler mehr Geld hätten, würden sie mehr Experimente durchführen.",
    "s.b2-02.4": "Wenn der Satellit nicht gestartet worden wäre, hätten wir das Phänomen nicht beobachtet.",
    "s.b2-02.5": "Wenn der Algorithmus nicht genau ist, sind die Vorhersagen nutzlos.",
    "s.b2-02.6": "Wäre die Hypothese bewiesen worden, hätte sie die Theorie völlig verändert.",
    "s.b2-02.7": "Künstliche Intelligenz kann Daten schneller analysieren als jeder Mensch.",
    "s.b2-02.8": "Der Durchbruch in der Genforschung wurde in einem kleinen Labor erzielt.",
    "s.b2-02.9": "Wenn Hacker in das System eingedrungen wären, wären Millionen von Konten in Gefahr.",
    "s.b2-02.10": "Die Automatisierung wird viele Berufe innerhalb eines Jahrzehnts überflüssig machen.",
    "s.b2-02.11": "Die Wissenschaftler haben die Teilchen mit hochmodernen Instrumenten gemessen.",
    "s.b2-02.12": "Wenn ich Wissenschaftler wäre, würde ich untersuchen, wie Zellen sich selbst reparieren.",
    "d.b2-02.1": "Dr. Adler, Ihr Team hat letzte Woche einen Durchbruch verkündet. Was genau haben Sie entdeckt?",
    "d.b2-02.2": "Wir haben einen Algorithmus entwickelt, der vorhersagt, wie bestimmte Zellen auf neue Medikamente reagieren.",
    "d.b2-02.3": "Wie genau ist er?",
    "d.b2-02.4": "In unseren Experimenten etwa neunzig Prozent. Wenn die Daten gut sind, sind die Vorhersagen zuverlässig.",
    "d.b2-02.5": "Was würde passieren, wenn ein Krankenhaus sich darauf verließe und er falsch wäre?",
    "d.b2-02.6": "Deshalb werden Ärzte immer die endgültige Entscheidung treffen. Das Werkzeug unterstützt sie nur.",
    "d.b2-02.7": "Manche Leute befürchten, dass künstliche Intelligenz Wissenschaftler überflüssig machen wird.",
    "d.b2-02.8": "Wenn das wahr wäre, hätten wir aufgehört, Forscher einzustellen. Stattdessen haben wir zehn weitere eingestellt.",
    "d.b2-02.9": "Und die Cybersicherheit? Patientendaten sind sensibel.",
    "d.b2-02.10": "Wenn die Daten nicht verschlüsselt und lokal gespeichert sind, verwenden wir sie nicht.",
    "d.b2-02.11": "Was kommt als Nächstes für das Labor?",
    "d.b2-02.12": "Wenn wir eine Finanzierung bekommen, führen wir nächsten Frühling eine größere Studie durch.",
    "m.b2-02": "Eine Erfindung, die die Welt verändert hat, ist ... . Sie wurde von ... in ... entwickelt. Wenn sie nicht erfunden worden wäre, ... . Heute wird sie benutzt, um ... . Wenn in der Zukunft ..., könnte sie ... .",
