    "p.b2-03.1": "Das Geschäft boomt.",
    "p.b2-03.2": "Wir arbeiten mit Verlust.",
    "p.b2-03.3": "Die Preise sind durch die Decke gegangen.",
    "p.b2-03.4": "Kommen wir zur Sache.",
    "p.b2-03.5": "Die Firma ging letztes Jahr in die Insolvenz.",
    "p.b2-03.6": "Die Nachfrage übersteigt derzeit das Angebot.",
    "p.b2-03.7": "Es ist eine riskante Investition, aber die Rendite könnte hoch sein.",
    "p.b2-03.8": "Einerseits..., andererseits...",
    "p.b2-03.9": "Wir müssen die Kosten auf ganzer Linie senken.",
    "p.b2-03.10": "Das Geschäft ist in letzter Minute geplatzt.",
    "p.b2-03.11": "Langfristig wird es sich auszahlen.",
    "p.b2-03.12": "Unser Marktanteil hat sich verdoppelt.",
    "s.b2-03.1": "Die Inflation stieg stark; infolgedessen gaben die Verbraucher weniger aus.",
    "s.b2-03.2": "Das Start-up brachte eine neue Marke auf den Markt; die Verkäufe blieben jedoch niedrig.",
    "s.b2-03.3": "Obwohl die Wirtschaft wächst, haben viele Familien immer noch Schwierigkeiten.",
    "s.b2-03.4": "Die Fusion wird die Kosten senken; außerdem wird sie die Effizienz verbessern.",
    "s.b2-03.5": "Erstens brauchen wir Investoren; zweitens brauchen wir ein realistisches Budget.",
    "s.b2-03.6": "Das Land exportiert Technologie, während es den Großteil seiner Lebensmittel importiert.",
    "s.b2-03.7": "Trotz der Rezession machte die Firma einen kleinen Gewinn.",
    "s.b2-03.8": "Die Prognose sagt langsames Wachstum voraus; deshalb sollten wir vorsichtig expandieren.",
    "s.b2-03.9": "Die Aktienkurse fielen nach der Insolvenz des größten Lieferanten.",
    "s.b2-03.10": "Konkurrenz hält die Preise niedrig, was am Ende den Verbrauchern zugutekommt.",
    "s.b2-03.11": "Die Unternehmerin finanzierte das Projekt mit ihren eigenen Ersparnissen.",
    "s.b2-03.12": "Denken Sie schließlich daran, dass jedes Geschäft ein gewisses Risiko birgt.",
    "d.b2-03.1": "Danke für Ihre Zeit. Unser Start-up stellt wiederverwendbare Verpackungen für Restaurants her.",
    "d.b2-03.2": "Interessant. Wie sieht die Nachfrage aus?",
    "d.b2-03.3": "Stark und wachsend. Erstens verbieten neue Vorschriften Einwegplastik; zweitens bevorzugen Verbraucher nachhaltige Marken.",
    "d.b2-03.4": "Ihre Produktionskosten scheinen jedoch hoch. Wie wollen Sie Gewinn machen?",
    "d.b2-03.5": "Anfangs werden wir mit einem kleinen Verlust arbeiten. Sobald wir expandieren, wird sich die Effizienz verbessern und die Kosten werden sinken.",
    "d.b2-03.6": "Und die Konkurrenz? Es gibt größere Firmen in diesem Markt.",
    "d.b2-03.7": "Stimmt, aber sie importieren ihre Produkte, während wir lokal herstellen und schneller liefern.",
    "d.b2-03.8": "Wie viel Finanzierung suchen Sie?",
    "d.b2-03.9": "Zwei Millionen, im Austausch für fünfzehn Prozent der Anteile.",
    "d.b2-03.10": "Das ist ehrgeizig. Außerdem geht die Prognose von keiner Rezession aus.",
    "d.b2-03.11": "Wir haben ein zweites Budget für eine schwächere Wirtschaft vorbereitet. Hier ist es.",
    "d.b2-03.12": "Gut. Schicken Sie mir den vollständigen Plan und wir sprechen nächste Woche.",
    "m.b2-03": "Die Wirtschaft von ... ist derzeit ... . Erstens ... . Infolgedessen ... . Jedoch ... . Außerdem ... . Deshalb wird langfristig ... .",
