    "w.b2-04.tragedy": "die Tragödie",
    "p.b2-04.1": "Das ist Auslegungssache.",
    "p.b2-04.2": "Der Roman wurde sofort ein Bestseller.",
    "p.b2-04.3": "Ich konnte das Buch nicht aus der Hand legen.",
    "p.b2-04.4": "Das Gemälde hat einen tiefen Eindruck auf mich gemacht.",
    "p.b2-04.5": "Die Melodie ging mir tagelang nicht aus dem Kopf.",
    "p.b2-04.6": "Sie hat eine lebhafte Fantasie.",
    "p.b2-04.7": "Die Ausstellung ist einen Besuch wert.",
    "p.b2-04.8": "Was meint der Autor damit?",
    "p.b2-04.9": "Das Ende hat mich völlig überrascht.",
    "p.b2-04.10": "Kunst ist Geschmackssache.",
    "p.b2-04.11": "Der Text ist wichtiger als die Musik.",
    "s.b2-04.1": "Die Veröffentlichung ihres ersten Romans veränderte ihr Leben.",
    "s.b2-04.2": "Die Darstellung der Armut in dem Film ist schmerzhaft realistisch.",
    "s.b2-04.3": "Die Interpretation der Skulptur durch den Kurator überraschte viele Besucher.",
    "s.b2-04.4": "Die Einsamkeit des Protagonisten ist das zentrale Thema des Romans.",
    "s.b2-04.5": "Die Komposition der Sinfonie kostete den Komponisten fast ein Jahrzehnt.",
    "s.b2-04.6": "Der Dichter benutzt das Meer als Metapher für die Erinnerung.",
    "s.b2-04.7": "Der Auftritt des Dirigenten auf der Bühne wurde mit lautem Applaus begrüßt.",
    "s.b2-04.8": "Abstrakte Kunst verlangt die aktive Teilnahme des Betrachters.",
    "s.b2-04.9": "Die Unzuverlässigkeit des Erzählers verleiht der Geschichte ihre Spannung.",
    "s.b2-04.10": "Das Porträt enthüllt die Traurigkeit hinter dem Lächeln des Königs.",
    "s.b2-04.11": "Der Dramatiker fand Inspiration in einer antiken griechischen Tragödie.",
    "s.b2-04.12": "Die Entscheidung der Galerie, junge Künstler zu zeigen, wurde weithin gelobt.",
    "d.b2-04.1": "Also, was haltet ihr alle von dem Roman?",
    "d.b2-04.2": "Ehrlich gesagt fand ich den Protagonisten schwer zu mögen, aber der Stil ist wunderschön.",
    "d.b2-04.3": "Was den Stil angeht, stimme ich zu. Der Umgang der Autorin mit Metaphern ist bemerkenswert.",
    "d.b2-04.4": "Der Fluss, der immer wiederkehrt, zum Beispiel. Ist er eine Metapher für die Zeit?",
    "d.b2-04.5": "Das ist eine Interpretation. Ich habe ihn als die Schuld des Erzählers gelesen.",
    "d.b2-04.6": "Interessant. Das Thema Schuld zieht sich tatsächlich durch das ganze Buch.",
    "d.b2-04.7": "Wusstest du, dass es von einem bekannten Dramatiker für die Bühne adaptiert wird?",
    "d.b2-04.8": "Wirklich? Ich frage mich, wie sie die Traumszenen darstellen werden.",
    "d.b2-04.9": "Wahrscheinlich mit Musik. Die Autorin sagte, der Rhythmus sei ihr wichtiger gewesen als die Handlung.",
    "d.b2-04.10": "Das erklärt, warum es sich stellenweise wie Dichtung liest.",
    "d.b2-04.11": "Sollen wir für nächsten Monat etwas Leichteres wählen?",
    "d.b2-04.12": "Ja, bitte. Eine Komödie, oder zumindest nicht noch eine Tragödie.",
    "m.b2-04": "Die Ausstellung bietet eine seltene Darstellung von ... . Die Wahl des Kurators, ..., erzeugt ... . Von besonderem Interesse ist ... . Die Kombination von ... und ... führt zu ... . Insgesamt ... .",
