    "p.b2-05.1": "Unschuldig, bis die Schuld bewiesen ist.",
    "p.b2-05.2": "Er bestritt alle Anschuldigungen.",
    "p.b2-05.3": "Die Geschworenen kamen zu einem Urteil.",
    "p.b2-05.4": "Ich bringe Sie vor Gericht.",
    "p.b2-05.5": "Sie bekam eine Geldstrafe wegen Falschparkens.",
    "p.b2-05.6": "Vor dem Gesetz sind alle gleich.",
    "p.b2-05.7": "Der Fall wurde aus Mangel an Beweisen eingestellt.",
    "p.b2-05.8": "Ist das überhaupt legal?",
    "p.b2-05.9": "Der Anwalt drängte seinen Mandanten, zu schweigen.",
    "p.b2-05.10": "Sie haben das Recht zu schweigen.",
    "p.b2-05.11": "Der Angeklagte wurde für nicht schuldig befunden.",
    "s.b2-05.1": "Der Angeklagte behauptete, er sei in jener Nacht zu Hause gewesen.",
    "s.b2-05.2": "Die Zeugin gab zu, dass sie das Gesicht des Mannes nicht gesehen hatte.",
    "s.b2-05.3": "Der Richter fragte die Zeugin, ob sie den Angeklagten erkenne.",
    "s.b2-05.4": "Der Anwalt bestand darauf, dass sein Mandant des Betrugs unschuldig sei.",
    "s.b2-05.5": "Die Polizei warnte die Bewohner davor, ihre Türen unverschlossen zu lassen.",
    "s.b2-05.6": "Die Firma wurde wegen Verletzung der Datenschutzvorschriften verklagt.",
    "s.b2-05.7": "Der Minister bestritt, dass die neue Gesetzgebung irgendwelche Rechte einschränken würde.",
    "s.b2-05.8": "Das Gericht entschied, dass das Verbot des Protests verfassungswidrig sei.",
    "s.b2-05.9": "Nach dem Urteil kündigte der Angeklagte an, dass er Berufung einlegen werde.",
    "s.b2-05.10": "Jeder Bürger hat nach der Verfassung Anspruch auf ein faires Verfahren.",
    "s.b2-05.11": "Die Ermittlung brachte Beweise für die Diskriminierung älterer Arbeitnehmer ans Licht.",
    "s.b2-05.12": "Die Reporterin sagte, der Mann sei wegen eines schweren Verbrechens verurteilt worden.",
    "d.b2-05.1": "Noa, du warst heute Morgen im Gerichtssaal. Was ist passiert?",
    "d.b2-05.2": "Der Prozess begann damit, dass die Staatsanwaltschaft neue Beweise gegen den Angeklagten vorlegte.",
    "d.b2-05.3": "Was hat der Angeklagte gesagt?",
    "d.b2-05.4": "Er bestand darauf, unschuldig zu sein, und behauptete, die Dokumente seien gefälscht worden.",
    "d.b2-05.5": "Haben Zeugen ausgesagt?",
    "d.b2-05.6": "Ja. Eine ehemalige Angestellte gab zu, dass sie die Verträge unterschrieben hatte, ohne sie zu lesen.",
    "d.b2-05.7": "Wie hat der Richter reagiert?",
    "d.b2-05.8": "Er warnte beide Seiten davor, mit der Presse zu sprechen, und fragte, ob weitere Beweise vorgelegt würden.",
    "d.b2-05.9": "Wird bald ein Urteil erwartet?",
    "d.b2-05.10": "Die Anwälte sagten mir, der Prozess werde wahrscheinlich noch drei Wochen dauern.",
    "d.b2-05.11": "Und wenn er wegen Betrugs verurteilt wird?",
    "d.b2-05.12": "Sein Anwalt hat bereits angekündigt, dass sie Berufung einlegen würden.",
    "m.b2-05": "Der Prozess gegen ... begann am ... . Der Angeklagte bestritt ... und behauptete, dass ... . Ein Zeuge gab zu, dass ... . Der Richter warnte ... . Der Anwalt bestand darauf, dass ..., und kündigte an, dass ... .",
