    "w.b2-06.deforestation": "die Abholzung",
    "w.b2-06.biodiversity": "die Artenvielfalt",
    "w.b2-06.global-warming": "die globale Erwärmung",
    "w.b2-06.threat": "die Bedrohung",
    "w.b2-06.to-tackle": "angehen",
    "w.b2-06.consequence": "die Folge",
    "w.b2-06.to-affect": "beeinträchtigen",
    "w.b2-06.vulnerable": "verletzlich",
    "w.b2-06.to-flee": "fliehen",
    "p.b2-06.1": "Es ist ein globales Problem, das eine globale Lösung braucht.",
    "p.b2-06.2": "Wir müssen das Bewusstsein schärfen.",
    "p.b2-06.3": "Millionen haben keinen Zugang zu sauberem Wasser.",
    "p.b2-06.4": "Global denken, lokal handeln.",
    "p.b2-06.5": "Die Kluft zwischen Arm und Reich wird größer.",
    "p.b2-06.6": "Die Zeit läuft uns davon.",
    "p.b2-06.7": "Jede Spende zählt, so klein sie auch sein mag.",
    "p.b2-06.8": "Die Gespräche endeten ohne Einigung.",
    "p.b2-06.9": "Das ist ein Tropfen auf den heißen Stein.",
    "p.b2-06.10": "Wir können es uns nicht leisten, das zu ignorieren.",
    "p.b2-06.11": "Vorbeugen ist billiger als Heilen.",
    "s.b2-06.1": "Angesichts einer schweren Dürre bat die Regierung um humanitäre Hilfe.",
    "s.b2-06.2": "Das 2015 unterzeichnete Abkommen zielt darauf ab, die globale Erwärmung zu begrenzen.",
    "s.b2-06.3": "An eine Hilfsorganisation zu spenden ist eine Möglichkeit, Ungleichheit anzugehen.",
    "s.b2-06.4": "Nachdem sie vor dem Konflikt geflohen sind, leben die Familien jetzt in Notunterkünften.",
    "s.b2-06.5": "Die Abholzung zerstört die Artenvielfalt und beeinträchtigt Millionen von Arten.",
    "s.b2-06.6": "Die letztes Jahr verhängten Sanktionen haben schwerwiegende Folgen gehabt.",
    "s.b2-06.7": "Die Pandemie breitete sich schnell über Grenzen aus und traf jedes Land.",
    "s.b2-06.8": "Aktivisten hoffen, dass die Schärfung des Bewusstseins zu echten Veränderungen führen wird.",
    "s.b2-06.9": "Der Botschafter warnte, dass Diplomatie allein den Konflikt nicht beenden würde.",
    "s.b2-06.10": "Die Verbesserung der Infrastruktur ist für die Entwicklung armer Regionen unerlässlich.",
    "s.b2-06.11": "Verletzliche Bevölkerungsgruppen leiden am meisten unter den Auswirkungen der Globalisierung.",
    "s.b2-06.12": "Ohne Zugang zu Bildung bleiben Kinder in der Armut gefangen.",
    "d.b2-06.1": "Dr. Mansour, wie ernst ist die Bedrohung durch die globale Erwärmung heute?",
    "d.b2-06.2": "Äußerst ernst. Nachdem ich die Daten zwanzig Jahre lang untersucht habe, kann ich sagen, dass die Veränderungen schneller sind als vorhergesagt.",
    "d.b2-06.3": "Yonatan, Ihre Organisation konzentriert sich auf die Abholzung. Warum?",
    "d.b2-06.4": "Weil das Abholzen von Wäldern die Artenvielfalt zerstört und gleichzeitig Kohlenstoff freisetzt.",
    "d.b2-06.5": "Was können normale Menschen tun?",
    "d.b2-06.6": "Spenden hilft, aber das Bewusstsein zu schärfen und für die richtige Politik zu stimmen ist wichtiger.",
    "d.b2-06.7": "Ich stimme zu. Regierungen reagieren auf Druck, wie wir beim letztes Jahr unterzeichneten Abkommen gesehen haben.",
    "d.b2-06.8": "Manche argumentieren, dass Sanktionen gegen verschmutzende Länder wirksamer wären.",
    "d.b2-06.9": "Sanktionen zu verhängen, ohne Hilfe anzubieten, schadet normalerweise den verletzlichsten Bevölkerungsgruppen.",
    "d.b2-06.10": "Genau. Diplomatie und Entwicklung müssen Hand in Hand gehen.",
    "d.b2-06.11": "Gibt es Grund zur Hoffnung?",
    "d.b2-06.12": "Ja. Erneuerbare Energie breitet sich schneller aus, als irgendjemand vor zehn Jahren erwartet hat.",
    "m.b2-06": "Nachdem wir ... als große Bedrohung erkannt haben, schlagen wir ... vor. Von ... finanziert, würde das Projekt ... . In Zusammenarbeit mit lokalen Gemeinschaften streben wir an, ... . Die Reduzierung von ... wird auch ... .",
    "w.c1-01.claim": "die Behauptung",
