    "w.c1-01.fallacy": "der Fehlschluss",
    "w.c1-01.bias": "die Voreingenommenheit",
    "w.c1-01.persuasive": "überzeugend",
    "w.c1-01.to-justify": "rechtfertigen",
    "w.c1-01.coherent": "schlüssig",
    "w.c1-01.contradiction": "der Widerspruch",
    "w.c1-01.to-assume": "annehmen",
    "w.c1-01.stance": "der Standpunkt",
    "w.c1-01.controversial": "umstritten",
    "w.c1-01.to-undermine": "untergraben",
    "w.c1-01.to-acknowledge": "anerkennen",
    "w.c1-01.to-advocate": "befürworten",
    "w.c1-01.opponent": "der Gegner",
    "w.c1-01.consensus": "der Konsens",
    "w.c1-01.debate": "die Debatte",
    "w.c1-01.to-outweigh": "überwiegen",
    "w.c1-01.nevertheless": "dennoch",
    "w.c1-01.whereas": "wohingegen",
    "p.c1-01.1": "Das ist ein berechtigter Einwand, aber er verfehlt das große Ganze.",
    "p.c1-01.2": "Zugegeben, die Beweislage ist begrenzt.",
    "p.c1-01.3": "Lassen Sie mich einen Moment den Advocatus Diaboli spielen.",
    "p.c1-01.4": "Ich verstehe Ihren Punkt, bin aber nicht überzeugt.",
    "p.c1-01.5": "Korrelation bedeutet nicht Kausalität.",
    "p.c1-01.6": "Sie widersprechen sich selbst.",
    "p.c1-01.7": "Einigen wir uns darauf, uns nicht einig zu sein.",
    "p.c1-01.8": "Die Beweislast liegt bei Ihnen.",
    "p.c1-01.9": "Dieses Argument hält einfach nicht stand.",
    "p.c1-01.10": "Bei allem Respekt, das ist nicht der Punkt.",
    "p.c1-01.11": "Worauf es hier ankommt, ist die langfristige Wirkung.",
    "p.c1-01.12": "Alles in allem überwiegen die Vorteile die Kosten.",
    "s.c1-01.1": "Obwohl ihre Behauptung überzeugend klingt, ist die Prämisse dahinter falsch.",
    "s.c1-01.2": "Zugegeben, die Politik ist umstritten; dennoch hat sie die Armut verringert.",
    "s.c1-01.3": "Es ist der Mangel an Beweisen, der sein ganzes Argument untergräbt.",
    "s.c1-01.4": "Diesen Punkt räume ich ein, wohingegen ich die Schlussfolgerung weiterhin ablehne.",
    "s.c1-01.5": "Ein schlüssiger Standpunkt erkennt Gegenargumente an, statt sie zu ignorieren.",
    "s.c1-01.6": "Auch wenn wir gute Absichten annehmen, beeinflusst Voreingenommenheit jede Entscheidung.",
    "s.c1-01.7": "Was einen Fehlschluss gefährlich macht, ist, dass er sich logisch anfühlt.",
    "s.c1-01.8": "Sie widerlegte die Behauptung des Gegners mit einer einzigen Statistik.",
    "s.c1-01.9": "Veränderung zu befürworten ist leicht; ihre Kosten zu rechtfertigen ist schwerer.",
    "s.c1-01.10": "Es gibt einen klaren Widerspruch zwischen seiner Prämisse und seiner Schlussfolgerung.",
    "s.c1-01.11": "Wissenschaftlicher Konsens bedeutet nicht, dass die Debatte für immer abgeschlossen ist.",
    "s.c1-01.12": "Im Gegenteil, die Daten stärken die Behauptung, statt sie zu schwächen.",
    "d.c1-01.1": "Omri, Sie argumentieren für die Wahlpflicht. Ihre Eingangsthese, bitte.",
    "d.c1-01.2": "Demokratie hängt von Beteiligung ab. Wenn die Hälfte der Bevölkerung zu Hause bleibt, spiegelt das Ergebnis eine verzerrte Stichprobe wider, nicht den Volkswillen.",
    "d.c1-01.3": "Leah, Ihre Antwort.",
    "d.c1-01.4": "Zugegeben, eine niedrige Wahlbeteiligung ist ein Problem. Dennoch untergräbt es die Freiheit, die Wahlen schützen sollen, wenn man Menschen zum Wählen zwingt.",
    "d.c1-01.5": "Ich räume ein, dass Freiheit wichtig ist. Allerdings akzeptieren wir bereits Steuerpflicht und Schöffendienst, wohingegen Wählen zehn Minuten dauert.",
    "d.c1-01.6": "Das ist ein falscher Vergleich. Steuern finanzieren Leistungen; eine erzwungene Stimme erzeugt zufällige Entscheidungen uninformierter Wähler.",
    "d.c1-01.7": "Omri, wie antworten Sie auf das Gegenargument der uninformierten Wähler?",
    "d.c1-01.8": "Was die Belege aus Australien zeigen, ist, dass die Wahlpflicht das politische Wissen mit der Zeit tatsächlich erhöht.",
    "d.c1-01.9": "Ein Land ist kaum ein Konsens. Außerdem nehmen Sie an, dass der Effekt hier derselbe wäre.",
    "d.c1-01.10": "Zugegeben, aber die Alternative, nichts zu tun, ist eindeutig gescheitert.",
    "d.c1-01.11": "Schlussplädoyers. Leah zuerst.",
    "d.c1-01.12": "Alles in allem überwiegen die Kosten für die Freiheit den ungewissen Nutzen. Überzeugen Sie die Menschen, zu wählen; zwingen Sie sie nicht.",
    "m.c1-01": "Es wird oft behauptet, dass ... . Zugegeben, ... . Dennoch zeigen die Belege, dass ... . Wohingegen Gegner argumentieren, dass ..., übersieht dies ... . Alles in allem ... .",
