    "w.c1-02.peer-pressure": "der Gruppendruck",
    "w.c1-02.manipulation": "die Manipulation",
    "w.c1-02.procrastination": "die Aufschieberitis",
    "w.c1-02.mindset": "die Denkweise",
    "w.c1-02.therapy": "die Therapie",
    "w.c1-02.willpower": "die Willenskraft",
    "w.c1-02.to-repress": "verdrängen",
    "w.c1-02.rational": "rational",
    "p.c1-02.1": "Das ist alles nur in deinem Kopf.",
    "p.c1-02.2": "Alte Gewohnheiten lassen sich schwer ablegen.",
    "p.c1-02.3": "Sie neigt dazu, zu viel nachzudenken.",
    "p.c1-02.4": "Vermutlich hat Stress eine Rolle gespielt.",
    "p.c1-02.5": "Er muss unter enormem Druck gestanden haben.",
    "p.c1-02.6": "In gewissem Maße sind wir alle voreingenommen.",
    "p.c1-02.7": "Ich konnte der Versuchung nicht widerstehen.",
    "p.c1-02.8": "Es scheint, dass Belohnungen besser wirken als Bestrafung.",
    "p.c1-02.9": "Zieh keine voreiligen Schlüsse.",
    "p.c1-02.10": "Man könnte argumentieren, dass die Persönlichkeit mehr von der Umwelt als von den Genen geprägt wird.",
    "p.c1-02.11": "Das kannst du damals nicht gewusst haben.",
    "s.c1-02.1": "Menschen mit hohem Selbstwertgefühl kommen möglicherweise besser mit Kritik zurecht.",
    "s.c1-02.2": "Aufschieberitis scheint eher mit Angst als mit Faulheit zusammenzuhängen.",
    "s.c1-02.3": "Extrovertierte Menschen neigen dazu, in sozialen Situationen Belohnungen zu suchen.",
    "s.c1-02.4": "Die Versuchsperson könnte die Erinnerung jahrelang verdrängt haben.",
    "s.c1-02.5": "Gruppendruck könnte in gewissem Maße erklären, warum Jugendliche Risiken eingehen.",
    "s.c1-02.6": "Unsere Wahrnehmung wird wohl von unterbewussten Vorurteilen geprägt.",
    "s.c1-02.7": "Anreize wirken vermutlich nur, wenn das Ziel erreichbar erscheint.",
    "s.c1-02.8": "Resilienz scheint teilweise von frühen Beziehungen abzuhängen.",
    "s.c1-02.9": "Er kann nicht impulsiv gehandelt haben; der Plan war zu detailliert.",
    "s.c1-02.10": "Therapie kann Patienten helfen, Manipulation in ihren Beziehungen zu erkennen.",
    "s.c1-02.11": "Intuition ist nicht immer irrational; oft spiegelt sie Erfahrung wider.",
    "s.c1-02.12": "Eine wachstumsorientierte Denkweise verbessert offenbar die kognitive Leistung bei Kindern.",
    "d.c1-02.1": "Dr. Peretz, warum treffen intelligente Menschen irrationale Entscheidungen?",
    "d.c1-02.2": "Intelligenz und Rationalität sind verschiedene Eigenschaften. Kluge Menschen sind vielleicht einfach besser darin, ihre Impulse zu rechtfertigen.",
    "d.c1-02.3": "Willenskraft ist also nicht die Antwort?",
    "d.c1-02.4": "Nur in gewissem Maße. Willenskraft neigt dazu, sich zu erschöpfen; ein unterstützendes Umfeld scheint wichtiger zu sein.",
    "d.c1-02.5": "Ihre Forschung zur Aufschieberitis hat viele Menschen überrascht.",
    "d.c1-02.6": "Vermutlich, weil wir annehmen, dass Aufschieber faul sind. Unsere Daten deuten darauf hin, dass sie oft ängstliche Perfektionisten sind.",
    "d.c1-02.7": "Könnten die sozialen Medien das verschlimmern?",
    "d.c1-02.8": "Möglicherweise. Der ständige Vergleich scheint das Selbstwertgefühl zu senken, besonders bei Jugendlichen, die Gruppendruck ausgesetzt sind.",
    "d.c1-02.9": "Gibt es etwas, das zuverlässig Resilienz aufbaut?",
    "d.c1-02.10": "Man könnte sagen: die Empathie eines vertrauten Erwachsenen. Die Belege sind nicht eindeutig, aber sie sind konsistent.",
    "d.c1-02.11": "Ein letzter Rat für unsere Leser?",
    "d.c1-02.12": "Behandeln Sie Ihre Intuition als Hypothese, nicht als Urteil. Dann überprüfen Sie sie.",
    "m.c1-02": "Die Forschung deutet darauf hin, dass ... dazu neigt, ... . Das könnte daran liegen, dass ... . In gewissem Maße ... . Es scheint, dass ..., obwohl die Belege ... sind. Vermutlich ... .",
    "w.c1-03.empire": "das Reich",
