    "w.c1-03.ideology": "die Ideologie",
    "w.c1-03.free-will": "der freie Wille",
    "w.c1-03.to-contemplate": "nachsinnen",
    "w.c1-03.paradox": "das Paradox",
    "w.c1-03.to-interpret": "deuten",
    "w.c1-03.turning-point": "der Wendepunkt",
    "p.c1-03.1": "Die Geschichte wiederholt sich.",
    "p.c1-03.2": "Wer die Vergangenheit vergisst, ist verdammt, sie zu wiederholen.",
    "p.c1-03.3": "Es markierte einen Wendepunkt in der europäischen Geschichte.",
    "p.c1-03.4": "Im Rückblick war der Zusammenbruch unvermeidlich.",
    "p.c1-03.5": "Der Zweck heiligt die Mittel, oder doch nicht?",
    "p.c1-03.6": "Ich denke, also bin ich.",
    "p.c1-03.7": "Erkenne dich selbst.",
    "p.c1-03.8": "Das wirft mehr Fragen auf, als es beantwortet.",
    "p.c1-03.9": "Die Geschichte wird von den Siegern geschrieben.",
    "p.c1-03.10": "Nicht nur fiel das Reich, sondern auch seine Sprache verschwand.",
    "p.c1-03.11": "Gibt es so etwas wie einen freien Willen?",
    "s.c1-03.1": "Nie zuvor war ein Reich so schnell und so vollständig zusammengebrochen.",
    "s.c1-03.2": "Die Revolution beendete nicht nur die Sklaverei, sondern definierte auch die Staatsbürgerschaft neu.",
    "s.c1-03.3": "Weil die Archive zerstört wurden, müssen Historiker Fragmente deuten.",
    "s.c1-03.4": "Erst nach der Unabhängigkeit begann das Land, seine eigene Geschichte zu schreiben.",
    "s.c1-03.5": "Antike Philosophen sannen darüber nach, ob Tugend gelehrt werden könne.",
    "s.c1-03.6": "Obwohl die Vernunft die Ethik leitet, entscheidet oft das Gefühl über unsere Moral.",
    "s.c1-03.7": "Wäre der König nicht gestürzt worden, hätte die Epoche der Reiche vielleicht fortgedauert.",
    "s.c1-03.8": "Die Skepsis leugnet das Wissen keineswegs, sondern fragt, wie wir es rechtfertigen.",
    "s.c1-03.9": "So mächtig war die Ideologie, dass Millionen sie ohne Frage akzeptierten.",
    "s.c1-03.10": "Das Paradox des freien Willens ist, dass wir uns frei fühlen und doch vorhersagbar handeln.",
    "s.c1-03.11": "Jede Zivilisation, die ihre Nachbarn eroberte, stand irgendwann vor demselben Schicksal.",
    "s.c1-03.12": "Was Philosophen Existenz nennen, nennen Historiker Kontext.",
    "d.c1-03.1": "Warum brach das Römische Reich zusammen? Shai, fangen wir mit Ihnen an.",
    "d.c1-03.2": "Traditionell machten Historiker die Invasionen verantwortlich. Nicht nur waren die Grenzen zu lang, sondern die Armee war auch erschöpft.",
    "d.c1-03.3": "Mor, Sie sind anderer Meinung?",
    "d.c1-03.4": "Teilweise. Wäre die Wirtschaft gesund gewesen, hätte das Reich die Invasionen überleben können, wie schon zuvor.",
    "d.c1-03.5": "Sie deuten den Zusammenbruch also eher wirtschaftlich als militärisch?",
    "d.c1-03.6": "Ja. Die Sklaverei machte Innovation unnötig, und als die Eroberungen aufhörten, endete auch der Nachschub an Sklaven.",
    "d.c1-03.7": "Das ist allerdings eine moderne Lesart. Die antiken Autoren selbst machten einen Verlust der Tugend verantwortlich.",
    "d.c1-03.8": "Was eine philosophische Frage aufwirft: Kann eine Zivilisation moralisch verfallen?",
    "d.c1-03.9": "Nur wenn wir annehmen, dass Moral mehr ist als Ideologie, was die Skeptiker bestreiten würden.",
    "d.c1-03.10": "Doch ohne eine gemeinsame Ethik hält keine Gesellschaft lange zusammen.",
    "d.c1-03.11": "Ausgezeichnet. Lesen Sie für nächste Woche die Archivquellen und entscheiden Sie, welchen Wendepunkt Sie am überzeugendsten finden.",
    "d.c1-03.12": "Und ob der Fall unvermeidlich war oder ob der freie Wille eine Rolle gespielt hat.",
    "m.c1-03": "Selten hat eine Frage die Denker so tief gespalten wie ... . Während die einen argumentieren, dass ..., halten andere daran fest, dass ... . Dies ist nicht nur für ... von Bedeutung, sondern auch ... . Nur durch ... können wir ... .",
