    "w.c1-04.to-convey": "vermitteln",
    "p.c1-04.1": "Anbei finden Sie den überarbeiteten Entwurf.",
    "p.c1-04.2": "Ich schreibe Ihnen mit Bezug auf Ihre E-Mail vom 3. Mai.",
    "p.c1-04.3": "Die Ergebnisse sind in Tabelle 2 zusammengefasst.",
    "p.c1-04.4": "Wie oben erwähnt, war die Stichprobe klein.",
    "p.c1-04.5": "Dies liegt außerhalb des Umfangs der vorliegenden Studie.",
    "p.c1-04.6": "Weitere Forschung ist erforderlich.",
    "p.c1-04.7": "Sollten Sie weitere Informationen benötigen, zögern Sie bitte nicht, mich zu kontaktieren.",
    "p.c1-04.8": "Zusammenfassend deuten die Belege darauf hin, dass...",
    "p.c1-04.9": "Könnten Sie klären, was Sie mit diesem Begriff meinen?",
    "p.c1-04.10": "Die Abgabefrist ist der 30. Juni.",
    "p.c1-04.11": "Es wurde argumentiert, dass...",
    "p.c1-04.12": "Ich freue mich darauf, Ihr Feedback zu erhalten.",
    "s.c1-04.1": "Es wird weithin argumentiert, dass eine klare Terminologie die Kohärenz verbessert.",
    "s.c1-04.2": "Die Daten wurden mit der im Anhang beschriebenen Methodik analysiert.",
    "s.c1-04.3": "Die Ergebnisse weisen auf einen starken Zusammenhang zwischen Schlaf und Gedächtnis hin.",
    "s.c1-04.4": "Quellen müssen korrekt zitiert werden, um Plagiate zu vermeiden.",
    "s.c1-04.5": "Der Vorschlag wurde vor der Frist eingereicht; folglich wurde er zuerst begutachtet.",
    "s.c1-04.6": "Ein mehrdeutiger Satz sollte umgeschrieben statt erklärt werden.",
    "s.c1-04.7": "Darüber hinaus reichen die Implikationen dieser Ergebnisse über die Bildung hinaus.",
    "s.c1-04.8": "Eine prägnante Gliederung wird erstellt, bevor der erste Entwurf geschrieben wird.",
    "s.c1-04.9": "Das Memo klärt den Umfang des Projekts für alle Abteilungen.",
    "s.c1-04.10": "Umformulieren vermittelt die Idee des Autors, ohne den Wortlaut zu kopieren.",
    "s.c1-04.11": "Sorgfältiges Korrekturlesen gilt vor der Einreichung als unerlässlich.",
    "s.c1-04.12": "Das Literaturverzeichnis führt jede Quelle auf, die in der Arbeit zitiert wurde.",
    "d.c1-04.1": "Nir, ich habe Ihren Entwurf gelesen. Der Methodikteil ist stark, aber die Einleitung ist zu lang.",
    "d.c1-04.2": "Das habe ich befürchtet. Soll ich den Hintergrund in einen Anhang verschieben?",
    "d.c1-04.3": "Teilweise. Fassen Sie die Geschichte in einem Absatz zusammen und zitieren Sie die Schlüsselquellen, statt sie zu beschreiben.",
    "d.c1-04.4": "Verstanden. Und das Ergebniskapitel?",
    "d.c1-04.5": "Die Daten sind gut dargestellt, aber mehrere Sätze sind mehrdeutig. Zum Beispiel ist das Wort signifikant hier unklar.",
    "d.c1-04.6": "Statistische Signifikanz. Ich werde die Terminologie klären.",
    "d.c1-04.7": "Gut. Darüber hinaus stellt der Abschnitt zu den Implikationen Behauptungen auf, die über den Umfang Ihrer Daten hinausgehen.",
    "d.c1-04.8": "Sie meinen den Teil über die nationale Politik?",
    "d.c1-04.9": "Genau. Entweder relativieren Sie diese Behauptungen oder Sie streichen sie. Sagen Sie, worauf die Ergebnisse hinweisen, nicht, was Sie zu beweisen hoffen.",
    "d.c1-04.10": "Ich werde den Abschnitt umformulieren und abschwächen. Noch etwas?",
    "d.c1-04.11": "Prüfen Sie das Literaturverzeichnis; zwei in Kapitel drei zitierte Quellen fehlen. Dann lesen Sie alles Korrektur, bevor Sie einreichen.",
    "d.c1-04.12": "Danke. Ich schicke bis Freitag einen überarbeiteten Entwurf.",
    "m.c1-04": "Diese Studie untersucht ... . Die Daten wurden von ... erhoben und mit ... analysiert. Die Ergebnisse weisen darauf hin, dass ... . Darüber hinaus ... . Folglich wird vorgeschlagen, dass ... . Die Implikationen für ... werden diskutiert.",
    "w.c2-01.register": "das Register",
